function link(url,label){return `<a href="${url}" target="_blank" rel="noreferrer">${label}</a>`}
function source(...a){return `<p class="source">${a.map(([u,t])=>link(u,t)).join(' · ')}</p>`}
function field(id){const [t,p]=fields[id];return `<div class="journal-field"><label for="j-${id}">${t}<span>${p}</span></label><textarea id="j-${id}" data-field="${id}" rows="5" placeholder="Hier beginnt deine Untersuchung …"></textarea><span class="field-saved" data-saved="${id}"></span></div>`}
function task(title,body,id){return `<section class="task"><p class="eyebrow">Deine Untersuchung</p><h3>${title}</h3>${body}${id?field(id):''}</section>`}
function head(kicker,title,lead){return `<header class="page-title intro"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${lead}</p></header>`}
function pagination(id){const i=route.findIndex(r=>r[0]===id);return `<nav class="pagination" aria-label="Weiter im Lernweg">${i>0?`<a href="#${route[i-1][0]}"><small>Zurück</small>${route[i-1][1]}</a>`:'<span></span>'}${i>=0&&i<route.length-1?`<a href="#${route[i+1][0]}"><small>Weiter</small>${route[i+1][1]}</a>`:'<a href="#auftakt"><small>Zum Anfang</small>Zwei Dichter unterwegs</a>'}</nav>`}
const pages={
auftakt:()=>`<section class="hero"><div class="hero-grid"><div class="hero-copy"><p class="eyebrow">Büchner · Celan / Eine literarische Wanderschaft</p><h1>Zwei Dichter.<br>Ein Gebirg.<br><em>Eine Suche.</em></h1><p class="lead">Ein Mensch geht durchs Gebirge. Ein anderer folgt seiner Spur – mehr als hundert Jahre später. Was sucht die Dichtung unterwegs?</p><div class="hero-actions"><a class="button" href="#elsass">Im Elsass aufbrechen</a><a class="textlink" href="#leseraum">Die Texte öffnen</a></div></div><div class="hero-art"><img src="assets/waldersbach.jpg" alt="Das Haus in Waldersbach, das Patrick Fischer in Georg B. als Oberlins Haus vorstellt."><div class="photo-label">Waldersbach / Elsass<small>Ein Ort der Zuflucht. Fotografie: Patrick Fischer · Zurichstories</small></div></div></div></section><div class="wrap"><div class="section-bar"><h2>Von einem Text<br>zum anderen.</h2><p>Lesen. Spuren verfolgen.<br>Eine eigene Deutung begründen.</p></div><div class="three"><article class="step"><span class="date">1778 / ERZÄHLT UM 1835</span><h3>Lenz</h3><p>Büchner erzählt von einem Dichter in einer Krise. Im elsässischen Steintal sucht Lenz bei Oberlin Halt. Die Natur, das Gespräch und die Kunst geben ihm jeweils nur vorübergehend Orientierung.</p><a href="#lenz">Büchners Erzählung untersuchen</a></article><article class="step"><span class="date">1959 / ERSCHIENEN 1960</span><h3>Gespräch im Gebirg</h3><p>Celan nimmt den Gang ins Gebirge wieder auf. Zwei jüdische Figuren sprechen. Die Büchner-Spur trifft auf Nietzsche und auf die Erinnerung an eine versäumte Begegnung mit Adorno.</p><a href="#gespraech">Celans Prosa untersuchen</a></article><article class="step"><span class="date">22. OKTOBER 1960</span><h3>Der Meridian</h3><p>In seiner Büchnerpreisrede liest Celan Büchner neu. Er fragt, wie Dichtung durch die Kunst hindurch zu einem Einzelnen und zu einem Gegenüber gelangen kann.</p><a href="#meridian">Celans Rede untersuchen</a></article></div></div><section class="band"><div class="wrap split"><div><p class="eyebrow">Die Leitfrage</p><h2>Was nimmt ein Text<br>auf seinem Weg mit?</h2><p class="lead">Eine Landschaft. Ein Datum. Eine Stimme. Und eine Geschichte, die sich nicht abschütteln lässt.</p><p>Die zwei Dichter dieses Lernwegs sind Büchner und Celan. Zwischen ihnen steht Jakob Michael Reinhold Lenz: historischer Autor, Büchners Figur und Celans Bezugspunkt. Ihre Wege begegnen sich in der Literatur.</p></div><div>${field('frage')}${field('vorwissen')}</div></div></section><div class="wrap"><p class="eyebrow">Deine Lernlandschaft</p><h2>Wähle deinen nächsten Schritt.</h2><div class="route-links">${route.slice(1).map((r,i)=>`<a class="route-link" href="#${r[0]}"><span class="route-icon" aria-hidden="true">${['⌂','◷','≋','∴','◯','⌘','▷','✎'][i]}</span><div><strong>${r[1]}</strong><small>${r[2]}</small></div></a>`).join('')}</div>${source([S.zurich,'Auftaktbild und Ortsgeschichte: Patrick Fischer, Georg B.'])}</div>`,
elsass:()=>`<div class="wrap">${head('Elsass · Vogesen · Waldersbach','Ein Haus.<br>Ein Mensch sucht Halt.','Am 20. Januar 1778 kommt Jakob Michael Reinhold Lenz zu Johann Friedrich Oberlin ins Steintal. Büchner wird aus den überlieferten Berichten eine Erzählung machen. Celan wird deren Gang durchs Gebirge weiterführen.')}<div class="split"><figure class="photo"><img src="assets/waldersbach.jpg" alt="Heutige Aufnahme eines grossen Hauses in Waldersbach mit Steintreppe, Fensterläden und Garten."><figcaption>Waldersbach, von Patrick Fischer auf <em>Georg B.</em> als Oberlins Haus vorgestellt. Eigene Aufnahme des Autors der Zurichstories-Seite. Das Foto zeigt den heutigen Erinnerungsort.${source([S.zurich,'Foto und Reiseeindruck im Original'])}</figcaption></figure><article><p class="eyebrow">Johann Friedrich Oberlin · 1740–1826</p><h2>Fürsorge hat<br>einen Ort.</h2><p>Oberlin ist Pfarrer in Waldersbach, dem Waldbach der Erzählung. Er nimmt Lenz auf. In Büchners Text gehört sein Handeln zu einem ganzen Alltag: Menschen besuchen, zuhören, beten, Wege und Kanäle anlegen, Schule halten.</p><p>Die Anwesenheit anderer und der geregelte Alltag beruhigen Lenz zeitweise. Nachts und während Oberlins Abwesenheit kehren Angst und innere Leere wieder. Der Text erzählt damit auch von Grenzen der Fürsorge und des religiösen Trostes.</p><div class="inset"><h3>Drei Zugänge zum selben Ort</h3><p><strong>Das Foto:</strong> ein heutiger Blick auf Waldersbach.<br><strong>Oberlins Bericht:</strong> die Perspektive des aufnehmenden Pfarrers.<br><strong>Büchners Erzählung:</strong> eine sprachlich gestaltete Nähe zu Lenz’ Wahrnehmung.</p></div><p>Patrick Fischer beschreibt auf Zurichstories den Frieden, den er bei seinem Besuch vor dem Haus empfand. Das ist ein persönlicher Reiseeindruck. Büchners Lenz erlebt Ruhe und Bedrohung im Wechsel. Prüfe, wie unterschiedlich derselbe Ort wahrgenommen werden kann.</p>${source([S.oberlin,'Oberlins Bericht: MBA 5, ab S. 219'],[S.lenz,'Büchners Text: MBA 5'])}</article></div>${task('Was kann ein Ort erzählen?','<ol><li>Beschreibe das Foto zunächst ohne Wissen über Lenz. Welche sichtbaren Merkmale erzeugen deinen Eindruck?</li><li>Lies im <a href="#leseraum/lenz">Leseraum</a> die Ankunft im Pfarrhaus und die folgende Nacht. Markiere den Wechsel zwischen Geborgenheit und Angst.</li><li>Vergleiche den Text mit Fischers Reiseeindruck. Begründe, was eine Fotografie über einen vergangenen inneren Zustand zeigen kann und was offenbleibt.</li></ol>','oberlin')}<section class="split"><article><p class="eyebrow">Vom Dokument zum Text</p><h2>Oberlin berichtet.<br>Büchner gestaltet.</h2><p>Eine wichtige Quelle ist Oberlins Bericht <em>Herr L......</em>. Die Marburger Ausgabe erschliesst ihn synoptisch und bietet zusätzlich einen quellenbezogenen Text von <em>Lenz</em>. Dort lässt sich die Nähe zu den Vorlagen untersuchen.</p><p>Quellennähe und literarische Gestaltung schliessen einander nicht aus: Schon Auswahl, Anordnung und Perspektive verändern, wie ein Mensch erscheint. Besonders am Anfang lässt Büchner uns Lenz’ schwankende Raum- und Selbstwahrnehmung sprachlich mitvollziehen.</p>${source([S.oberlin,'Oberlin: synoptischer Text'],[S.quellentext,'Lenz: quellenbezogener Text'],[S.edition,'Editionsbericht'])}</article><div>${task('Eine Übernahme genau prüfen','<p>Öffne Oberlins Bericht und den quellenbezogenen Text nebeneinander. Suche einen kurzen gemeinsamen Vorgang. Notiere Wortlaut und Fundorte in beiden Texten. Unterscheide eine nachweisbare Übernahme von deiner Deutung ihrer Wirkung.</p>','quelle')}</div></section><div class="inset"><h3>Das Elsass reist in Celans Text weiter.</h3><p>Der Bezug führt vom elsässischen <em>Lenz</em> zum <em>Gespräch im Gebirg</em>. Celan selbst verbindet beide Texte später im <em>Meridian</em>. Dazu kommt der Engadiner Zusammenhang mit Nietzsche und Adorno. Die Landschaft wird so zu einem Raum mehrerer Texte und Zeiten.</p><a href="#gespraech">Die zweite Gebirgswanderung</a></div>${pagination('elsass')}</div>`,
leben:()=>`<div class="wrap">${head('Biografie & Zeitgeschichte','Wer geht?<br>Und aus welcher Zeit?','Die Wanderschaft bedeutet für Lenz, Büchner und Celan jeweils etwas anderes. Untersuche Verbindungen, ohne ihre Lebensgeschichten gleichzusetzen.')}<div class="tabs" aria-label="Lebensweg wählen"><button data-life="lenz" aria-pressed="true">Jakob Michael Reinhold Lenz</button><button data-life="buechner" aria-pressed="false">Georg Büchner</button><button data-life="celan" aria-pressed="false">Paul Celan</button></div><div id="life-panel"></div><section class="band task"><h3>Ein Motiv trägt verschiedene Geschichten.</h3><div class="table-scroll"><table class="comparison"><thead><tr><th>1778 · Lenz</th><th>1830er · Büchner</th><th>1959/60 · Celan</th></tr></thead><tbody><tr><td>Sturm und Drang; prekäre Existenz eines Autors; Krise und Suche nach Aufnahme.</td><td>Vormärz; soziale Ungleichheit, Zensur und politische Verfolgung; wissenschaftliche und literarische Arbeit im Exil.</td><td>Nach der Shoah; Verlust der Eltern, Zwangsarbeit und Migration; Weiterdichten auf Deutsch; Frage nach Erinnerung und Ansprechbarkeit.</td></tr><tr><td>Oberlin als religiöses und praktisches Gegenüber.</td><td>Fürsorge für die Kreatur und Kritik an idealisierender Darstellung als Lesefragen.</td><td>Das Gegenüber als Hoffnung der Dichtung; Geschichte bleibt im Sprechen gegenwärtig.</td></tr></tbody></table></div><p>Die zweite Zeile formuliert Lektüreperspektiven. Belege sie an den Texten. Biografie erklärt weder jede Einzelheit noch ersetzt sie sprachliche Analyse.</p>${field('zeiten')}</section>${pagination('leben')}</div>`,
lenz:()=>`<div class="wrap">${head('Georg Büchner · Lenz','Die Landschaft<br>gerät ins Schwanken.','Büchner erzählt keine gleichmässige Wanderung. Nähe und Ferne, Glück und Angst, Ich und Welt wechseln ihre Beziehung – oft mitten im Satz.')}<div class="split wide-left"><article><blockquote>„Den 20. ging Lenz durch’s Gebirg.“<cite>Büchner, Lenz · Anfang der verlinkten Gutenberg-Fassung. Apostroph typografisch angepasst.</cite></blockquote><p>Der Anfang nennt einen Tag, aber in dieser Fassung keinen Monat. Andere Ausgaben und Celans <em>Meridian</em> führen den „20. Jänner“. Schon eine scheinbar feste Textspur verlangt also eine Angabe der benutzten Ausgabe.</p><p>Die Erzählung hält sich oft nahe an Lenz’ Wahrnehmung: Die Welt scheint zusammenschiebbar, die Erde klein, später öffnet sich eine erschreckende Leere. Wiederholungen und lange Satzbewegungen lassen die Orientierung selbst unsicher werden. Untersuche dabei genau, wer wahrnimmt und wer erzählt.</p><p>Im Pfarrhaus findet Lenz zeitweise Geborgenheit. Religiöse Hoffnung und Verzweiflung wechseln. Das Kunstgespräch stellt eine weitere Suche dar: Wie lässt sich lebendiges, einzelnes menschliches Leben darstellen?</p><a class="button" href="#leseraum/lenz">Lenz im Leseraum öffnen</a>${source([S.gutenberg,'Volltext bei Projekt Gutenberg'],[S.lenz,'Emendierter Text: Marburger Ausgabe'])}</article><aside class="inset"><h3>Drei Lektüregänge</h3><p><strong>Wahrnehmung:</strong> der Anfang bis zur Ankunft in Waldbach.</p><p><strong>Kunst:</strong> das Gespräch über Literatur, Idealismus, Natur und die beiden Mädchen.</p><p><strong>Beziehung:</strong> Oberlins Abwesenheit, die Rückkehr und der Schluss.</p><p>Lies zunächst den ganzen Text. Kehre danach mit einer eigenen Frage zu einer dieser Stellen zurück.</p></aside></div>${task('Wie erzählt man einen Verlust von Orientierung?','<ol><li>Wähle einen Abschnitt aus dem Anfang. Sammle Wörter für Bewegung, Entfernung, Körper und Wahrnehmung.</li><li>Zeige an Satzbau oder Wiederholung, wie der Wechsel von Weltgefühl und Angst gestaltet wird.</li><li>Formuliere eine Deutung mit Beleg und einer alternativen Lesart. Vermeide eine nachträgliche medizinische Diagnose.</li></ol>','lenz')}<section class="split"><article><p class="eyebrow">Das Kunstgespräch</p><h2>Lebendig sehen.<br>Oder in Stein bannen?</h2><p>Die Figur Lenz wendet sich gegen idealisierte Figuren und verlangt Aufmerksamkeit für das Leben einzelner Menschen. Doch das Bild der beiden Mädchen führt zu einem Widerspruch: Ausgerechnet der Wunsch, lebendiges Leben festzuhalten, ruft das versteinernde Medusenhaupt auf.</p><p>Celan setzt an diesem Widerspruch an. Im <em>Meridian</em> fragt er nach dem Unheimlichen einer Kunst, die Menschen zum Bild und zum Mechanismus werden lässt. Diese Lektüre ist Celans eigener, ausdrücklich gegenwartsbezogener Akzent.</p><p>Unterscheide vier Stimmen: den historischen Lenz, Büchners Figur, den Erzähler und Celan als Leser. Eine Figurenrede ist nicht ohne Weiteres ein direktes Bekenntnis ihres Autors.</p></article><div>${task('Eine Auffassung von Kunst – zwei Lektüren','<p>Lies das Kunstgespräch bei Büchner und die Passage „Lenz, also Büchner“ in der bereitgestellten Meridian-Datei. Was hebt Celan hervor? Was lässt er im Hintergrund? Notiere zunächst deinen eigenen Befund.</p>','kunst')}</div></section><details><summary>Überlieferung: Warum die Ausgabe mitlesen?</summary><p>Der Text erschien 1839 nach Büchners Tod. Das Manuskript ist nicht erhalten; die Drucküberlieferung und die Eingriffe der Herausgeber sind deshalb besonders wichtig. Die Marburger Ausgabe unterscheidet den emendierten Text, quellenbezogene Darstellung, Quellen und Drucke. Celan nennt <em>Lenz</em> ein Fragment. Für die heutige Untersuchung bleibt die Frage nach Abschluss und Textgestalt eine editorische Frage.</p>${source([S.edition,'Editionsbericht ab S. 75'],[S.mba+'introduction','Einführung zur Edition'])}</details>${pagination('lenz')}</div>`,
gespraech:()=>`<div class="wrap">${head('Paul Celan · 1959 / 1960','Noch einmal<br>durchs Gebirg.','Die Spur beginnt im Elsass bei Büchners Lenz. Im Gespräch im Gebirg führt Celan sie in einen anderen sprachlichen und geschichtlichen Horizont: zu jüdischer Erfahrung, Nietzsche und Adorno.')}<div class="path-map" aria-label="Drei miteinander verbundene Bezugsräume"><div><strong>Elsass</strong><span>Lenz, Oberlin und Büchners Erzählung</span></div><div><strong>Engadin</strong><span>Nietzsche; versäumte Begegnung mit Adorno</span></div><div><strong>Im Text</strong><span>Zwei Stimmen, eine Suche nach Anrede</span></div></div><div class="split"><article><h2>Ein Gang wird<br>zum Gespräch.</h2><p>Celans 1959 geschriebener und 1960 publizierter Prosatext lässt die Figuren „Jud Klein“ und „Jud Gross“ aufeinandertreffen. In den Ausgaben steht gewöhnlich „Groß“. Die Bezeichnungen gehören zur gestalteten Sprache des Textes.</p><p>Wiederholungen, Zusätze, Anreden und Fragen lassen den Text wie gesprochen klingen. Aber Sprechen und Verstehen fallen nicht einfach zusammen. Stein, Stock, Schatten und Landschaft werden Teil der Frage, wer sprechen und wem etwas zugehören kann.</p><p>Der Bezug auf Büchners Gebirgsgang ist nicht bloss eine ähnliche Kulisse: Im <em>Meridian</em> erklärt Celan ausdrücklich, in dieser Geschichte einen Menschen wie Lenz gehen gelassen zu haben. Das ist der stärkste Ausgangspunkt für den Textvergleich.</p>${source([S.gespraech,'DLA Marbach: vollständige Lesung, Hanns Zischler'],[S.meridian,'Meridian: Celans eigener Rückbezug'])}<p class="source">Arbeite parallel mit einer Textausgabe: Paul Celan, <em>Gespräch im Gebirg</em>, in <em>Gesammelte Werke</em>, Band III, S. 169–173. Trage beim Zitieren die Seiten deiner Ausgabe ein. Die DLA-Lesung ist hier als Hörzugang verlinkt.</p><a class="button" href="#leseraum/gespraech">Hör- und Arbeitsraum öffnen</a></article><article>${task('Höre auf die Bewegung der Sprache','<ol><li>Lies oder höre den Anfang zunächst ohne Deutungshilfe. Notiere eine Irritation.</li><li>Verfolge eine Wiederholung und eine Anrede. Wer spricht hier zu wem? Wo wird das unsicher?</li><li>Vergleiche eine sprachliche Bewegung mit dem Anfang von <em>Lenz</em>. Benenne Gemeinsamkeit und Veränderung.</li></ol>','gespraech')}</article></div></div><section class="dark"><div class="wrap split"><article><p class="eyebrow">Nietzsche · Zarathustra</p><h2>Wer steigt herab?<br>Wer hört zu?</h2><p>Auch Nietzsches Zarathustra verlässt seine Heimat und geht ins Gebirge. Nach Jahren der Einsamkeit steigt er herab und sucht Menschen. Sonne, Tageszeit, Schatten und die Frage nach dem Gegenüber geben dem Vergleich mit Celan konkrete Ansatzpunkte.</p><p>Lies den Abend und die zwei jüdischen Sprecher bei Celan als mögliche Gegenbewegung zu Zarathustras Verkündigung. Das ist eine zu prüfende Deutung, kein Schlüssel, der jedes Wort erklärt. Zeige, wo sich der Anspruch einer grossen Rede verändert, wenn ein einzelnes Ich ein Du sucht.</p>${source([S.nietzsche,'Nietzsche Source: Zarathustras Vorrede'],[S.sils,'Nietzsche-Haus: Sils Maria und die Wanderungen'])}</article><div>${task('Eine Konstellation statt eines Schlagworts','<p>Stelle je eine kurze Passage von Nietzsche und Celan nebeneinander. Vergleiche Aufbruch, Richtung, Tageszeit und Sprechhaltung. Entscheide dann, ob „Anspielung“, „Umkehrung“ oder „produktive Spannung“ deinen Befund am besten beschreibt. Begründe deine Wortwahl.</p>','nietzsche')}</div></div></section><div class="wrap split"><article><p class="eyebrow">Adorno · Sommer 1959</p><h2>Eine versäumte<br>Begegnung.</h2><p>Im Engadin kommt ein erhofftes Treffen mit Theodor W. Adorno nicht zustande. Celan erinnert im <em>Meridian</em> selbst an diese versäumte Begegnung. Der Prosatext eröffnet einen sprachlichen Begegnungsraum.</p><p>Die Beziehung zu Adorno führt zur Frage, was Kunst nach Auschwitz vermag. Adornos Kritik an Kultur nach der Katastrophe ist als Herausforderung zu lesen. Seine Äusserungen verändern sich; eine pauschale Formel vom Verbot aller Gedichte verdeckt die Auseinandersetzung.</p><p>Eine weitere Spur führt direkt ins Elsass zurück: Büchners Lenz bezeichnet sich gegenüber Oberlin als „der ewige Jude“. Diese Selbstbezeichnung steht im Zusammenhang seiner Verzweiflung und greift ein christlich überliefertes, antijüdisch belastetes Wandermotiv auf. Celans jüdische Sprecher tragen dagegen eine konkrete Geschichte von Verfolgung und Überleben mit. Prüfe, was sich verändert, wenn aus einer Metapher der Heimatlosigkeit eine jüdische Sprechposition wird.</p><p>Die Figuren können auf Celan und Adorno bezogen werden. Sie gehen darin nicht auf. Ein erzähltes Gespräch ist kein Protokoll des ausgebliebenen Treffens. Prüfe, welche zusätzlichen Fragen nach jüdischer Zugehörigkeit, Wahrnehmung und Selbstbegegnung die Prosa stellt.</p>${source([S.adorno,'Joachim Seng: Celan und Adorno'],[S.gespraech,'DLA: Entstehungskontext der Erzählung'])}</article><div>${task('Wo endet das Wissen, wo beginnt die Deutung?','<p>Formuliere drei Sätze: einen über den belegten Entstehungsanlass, einen über eine intertextuelle Beobachtung und einen über deine Interpretation. Kennzeichne die unterschiedliche Sicherheit. Frage danach, wie sich diese Konstellation im <em>Meridian</em> weiterentwickelt.</p>','adorno')}</div>${pagination('gespraech')}</div>`,
meridian:()=>`<div class="wrap">${head('Darmstadt · 22. Oktober 1960 · Georg-Büchner-Preis','Der Weg<br>zum Gegenüber.','Celan dankt für einen Preis, indem er mit Büchner über die Möglichkeit von Dichtung nachdenkt. Die Rede sucht, fragt und korrigiert sich – sie geht ihren eigenen Weg.')}<div class="split"><article><h2>Mit Büchner<br>durch die Kunst.</h2><p>Die Rede beginnt mit Kunst als Marionette, führt über den Affen im <em>Woyzeck</em> und die Automaten in <em>Leonce und Lena</em> zum Kunstgespräch in <em>Lenz</em>. Gemeinsam ist diesen Bildern die Frage, wie Lebendiges zum vorgeführten Kunstwesen wird.</p><p>Luciles Ausruf aus <em>Dantons Tod</em> liest Celan als Gegenwort: Ein einzelner Mensch tritt dem fertigen Reden entgegen. Bei Lenz sucht er eine andere Grenzerfahrung. Aus dem unmöglichen Gehen auf dem Kopf gewinnt Celan das Bild des Himmels als Abgrund.</p><p>Die Suche führt über Atemwende und Aufmerksamkeit zur Begegnung. Ein Gedicht ist von einer einzelnen Existenz und ihren Daten geprägt; gerade so kann es sich einem anderen zuwenden. Die Meridian-Figur am Ende verbindet Herkunft, Umweg und Rückkehr.</p><a class="button" href="#leseraum/meridian">Die vollständige Rede lesen</a>${source([S.meridian,'Offizielle Fassung der Deutschen Akademie'],[S.preis,'Preisverleihung und historische Tonaufnahme'])}</article><aside>${task('Folge einer Denkbewegung','<p>Lies die Rede vollständig. Wähle dann zwei Begriffe aus dem Leseraum. Erläutere ihren Zusammenhang anhand des jeweiligen Büchner-Bezugs. Achte auf die vielen Fragen und „Vielleicht“-Formulierungen: Wo hält Celan seine Aussagen offen?</p>','meridian')}</aside></div><div class="inset"><h3>Von der Woyzeck-Seite hierher</h3><p>Der Jahrmarkt zeigt einen Ausrufer, eine Kreatur und eine Vorführung. Celan hört darin die Frage nach Kunst und Mechanismus. Vergleiche die Szene mit der Rede: Welche Funktion gibt Celan dem Affen, und welche sozialen und dramatischen Zusammenhänge hat die Szene bei Büchner zusätzlich?</p>${source([S.woyzeck+'#handschrift','Originalseite und Umschrift in der Montagewerkstatt'],['https://www.marburger-buechner-ausgabe.de/textview?ccl1=43&p1=4&l1=6','MBA: Woyzeck H1,1'])}</div><section class="split"><article><p class="eyebrow">Daten lesen</p><h2>Der 20. Jänner<br>bleibt eingeschrieben.</h2><p>Celan nimmt den Tag des Gebirgsgangs als Formel für die geschichtliche und persönliche Prägung eines Gedichts. Der Januar 1778 gehört zur Lenz-Geschichte; die Rede fragt darüber hinaus nach den Daten, von denen wir uns herschreiben.</p><p>Ein historischer Resonanzraum ist der 20. Januar 1942, das Datum der Wannsee-Konferenz. Die Verbindung ist eine Deutung; Celan benennt die Konferenz in der Rede nicht ausdrücklich. Der nationalsozialistische Massenmord hatte bereits zuvor begonnen. Auf der Konferenz wurde dessen europaweite Organisation koordiniert.</p><p>Prüfe die Reichweite der Datumsverbindung: Sie macht den Tag nicht zu einem eindeutigen Geheimcode. Die Frage nach Erinnerung darf die konkrete Textbewegung und die je eigenen Daten der anderen nicht auslöschen.</p>${source([S.wannsee,'Haus der Wannsee-Konferenz: Protokoll und Dokumente'])}</article><div>${task('Ein Datum, mehrere Ebenen','<p>Halte zunächst fest, was in deiner Lenz-Ausgabe und im Meridian tatsächlich steht. Ergänze den historischen Kontext von 1942. Formuliere danach vorsichtig, welchen Erkenntnisgewinn die Verbindung hat und wo ihre Grenze liegt.</p>','datum')}</div></section>${pagination('meridian')}</div>`,
spuren:()=>`<div class="wrap">${head('Intertextualität · Werkstatt','Verbindungen<br>brauchen Belege.','Ein gemeinsames Wort ist ein Anfang. Eine tragfähige intertextuelle Deutung zeigt, wie ein Text einen anderen aufnimmt, verschiebt oder befragt.')}<div class="connection-layout"><div class="connection-list" aria-label="Textverbindung auswählen">${connections.map((c,i)=>`<button data-connection="${i}" aria-pressed="${i===0}"><small>${c.kind}</small>${c.title}</button>`).join('')}</div><article id="connection-panel" class="connection-panel"></article></div>${task('Baue deinen eigenen Zusammenhang','<ol><li>Wähle eine Verbindung oder entwickle eine eigene. Sammle zwei kurze Belege mit Fundorten.</li><li>Beschreibe zuerst die beobachtbare Beziehung: Zitat, expliziter Rückbezug, Motiv, sprachliche Form oder Kontrast.</li><li>Erkläre die Veränderung. Beziehe einen historischen Rahmen ein und benenne eine Grenze deiner Deutung.</li><li>Besprich deinen Befund mit jemandem, der eine andere Verbindung gewählt hat.</li></ol>','spuren')}<details><summary>Eine mögliche Deutung als Gegenprobe lesen</summary><p>Ein möglicher Zusammenhang lautet: Die Bewegung durch das Gebirge wird von Büchners Erzählung einer erschütterten Wahrnehmung zu Celans Suche nach Anrede und schliesslich zum poetologischen Wegbild. Diese These ist erst belastbar, wenn sie Stellen aus allen drei Texten erklärt. Sie muss zugleich berücksichtigen, dass auch Büchners Lenz Gespräche sucht und Celans Gespräch keineswegs mühelos gelingt.</p><p>Prüfe diese Lesart an deinem eigenen Befund. Welche Stelle bestätigt sie, welche begrenzt sie?</p></details>${pagination('spuren')}</div>`,
filme:()=>`<div class="wrap">${head('Medienraum · Zwei mitgebrachte Filme','Ein Leben.<br>Zwei filmische Blicke.','Die Filme erschliessen Celans Lebensgeschichte und machen zugleich eigene Bilder von ihm. Beobachte, wie Stimme, Archivmaterial, Landschaft und Schrift deine Lektüre lenken.')}<div class="film-grid"><article><figure><video id="film-portrait" controls playsinline preload="none" poster="assets/celan-portrait.jpg" aria-label="Paul Celan – Dichter ist, wer menschlich spricht"><source src="${releaseBase}Paul.Celan.-.Dichter.ist.wer.menschlich.spricht.Portrait.2014.mp4" type="video/mp4">${link(releaseBase+'Paul.Celan.-.Dichter.ist.wer.menschlich.spricht.Portrait.2014.mp4','Film als Datei öffnen')}</video><figcaption>Bereitgestelltes Porträt, Dateititel mit Jahresangabe 2014 · 44:43 Minuten. Senderkennung im Material: 3sat. Standbild aus der bereitgestellten Datei.</figcaption></figure><h3>Dichter ist, wer menschlich spricht</h3><p>Untersuche, wie der Film Beziehungen zwischen biografischen Erfahrungen und Dichtung herstellt. Eine biografische Aussage und eine Interpretation eines Gedichts benötigen jeweils eigene Belege.</p><button type="button" class="primary" data-timestamp="portrait">Aktuellen Zeitpunkt notieren</button>${source([releaseBase+'Paul.Celan.-.Dichter.ist.wer.menschlich.spricht.Portrait.2014.mp4','Film öffnen / herunterladen'])}${field('film1')}</article><article><figure><video id="film-antschel" controls playsinline preload="none" poster="assets/antschel.jpg" aria-label="Antschel – Filmessay über Paul Celan"><source src="${releaseBase}ANTSCHEL.Filmessay.about.Paul.Celan.mp4" type="video/mp4">${link(releaseBase+'ANTSCHEL.Filmessay.about.Paul.Celan.mp4','Film als Datei öffnen')}</video><figcaption><em>Antschel</em> · Filmessay von Susanne Ayoub über Paul Celan und seine Freundschaft mit Klaus Demus · bereitgestellte Datei, 45:29 Minuten. Standbild aus der Datei.</figcaption></figure><h3>Antschel</h3><p>Der Filmessay verbindet Orte, Gedichte und die Erinnerung von Klaus Demus. Achte auf die Perspektive eines Weggefährten und darauf, wie Heimat in der Sprache filmisch gestaltet wird.</p><button type="button" class="primary" data-timestamp="antschel">Aktuellen Zeitpunkt notieren</button>${source([S.antschel,'Alte Schmiede: Film und Perspektive'],[releaseBase+'ANTSCHEL.Filmessay.about.Paul.Celan.mp4','Film öffnen / herunterladen'])}${field('film2')}</article></div>${task('Biografisches Wissen trifft auf filmische Form','<p>Vergleiche eine von dir gewählte Sequenz aus jedem Film. Notiere Zeitpunkte und prüfe eine Aussage mit einer biografischen Quelle. Verbinde danach die filmische Darstellung mit einer Passage aus einem der drei Texte. Die Filmprotokolle werden nicht automatisch zu einer Transkription oder Bewertung ergänzt.</p>','filmvergleich')}${pagination('filme')}</div>`,
journal:()=>`<div class="wrap">${head('Dein Denkprotokoll','Aus Spuren<br>wird eine These.','Hier kommen deine Untersuchungen zusammen. Eine starke Deutung erklärt ihre Belege, hält historische Unterschiede aus und reagiert auf Einwände.')}<div class="inset"><h3>Deine Einträge gehören dir.</h3><p>Die Speicherung erfolgt in diesem Browser, ohne Konto und ohne gemeinsame Klassenablage. Sichere deine Daten vor einem Gerätewechsel oder dem Löschen von Browserdaten. Das Öffnen einer Station ist kein Nachweis von Lernerfolg.</p><p id="storage-state"></p></div><div class="toolbar"><button class="primary" data-action="export-text">Text exportieren</button><button data-action="export-json">Sicherung herunterladen</button><button data-action="print">Drucken / PDF</button></div><label for="import-file">Sicherungsdatei wiederherstellen<span>Eine gültige Sicherung ersetzt deine aktuellen Einträge erst nach deiner Bestätigung.</span></label><input type="file" id="import-file" accept="application/json,.json"><div id="import-preview" hidden></div><section class="task">${field('frage')}${field('these')}${field('gegenbeleg')}${field('rueckmeldung')}${field('revision')}</section><section class="task"><p class="eyebrow">Dein Lernprodukt</p><h2>Eine argumentierte<br>literarische Wanderschaft.</h2><p>Schreibe einen Vergleichsessay von etwa 800–1200 Wörtern oder gestalte einen zehnminütigen Audioessay mit schriftlichem Belegblatt. Entwickle eine eigene Antwort auf deine Forschungsfrage.</p><ol><li>Gehe von einer präzisen Textbeobachtung aus.</li><li>Untersuche einen Zusammenhang zwischen <em>Lenz</em>, <em>Gespräch im Gebirg</em> und <em>Meridian</em>.</li><li>Binde Oberlin und das Elsass sowie Nietzsche und Adorno begründet ein.</li><li>Erkläre eine historische Differenz zwischen Büchners Vormärz und Celans Schreiben nach der Shoah.</li><li>Prüfe deine These an einem Gegenbeleg und formuliere ein differenziertes Ergebnis.</li></ol>${field('essay')}</section><section class="checklist"><h3>Vor der Abgabe selbst prüfen</h3>${['Ich unterscheide Autor, Figur, Erzähler und Leser.','Meine Textbelege haben überprüfbare Fundorte.','Ich erkläre die Funktion der intertextuellen Bezüge.','Ich unterscheide historischen Befund und Deutung.','Ich prüfe einen Einwand und überarbeite meine These.'].map((x,i)=>`<label><input type="checkbox" data-check="${i}">${x}</label>`).join('')}</section><h2 style="margin-top:50px">Deine bisherigen Untersuchungen</h2><div class="journal-grid">${Object.keys(fields).filter(x=>!['frage','these','gegenbeleg','rueckmeldung','revision','essay'].includes(x)).map(x=>`<section class="task">${field(x)}</section>`).join('')}</div>${pagination('journal')}</div>`,
quellen:()=>`<div class="wrap narrow">${head('Quellen & Materialien','Nachlesen.<br>Nachprüfen.','Primärtexte, Editionsmaterial, biografische Quellen und die Herkunft der Bilder sind nach ihrer Funktion ausgewiesen.')}<ul class="source-list">${sources.map(x=>`<li><strong>${link(x[1],x[0])}</strong><p>${x[2]}</p></li>`).join('')}</ul><h2>Die bereitgestellten Materialien</h2><p>${link('materialien/Celan_Meridian.docx','Celan_Meridian.docx herunterladen')} · Der Leseraum übernimmt den Text aus dieser Datei. „M“-Absatznummern dienen nur der Orientierung in dieser Lernumgebung; sie sind keine Nummerierung der Originalausgabe.</p><p>Die beiden Filmdateien liegen unverändert als Anlagen des ${link('https://github.com/PatrickFischerKSA/lenz-celan-lernlandschaft/releases/tag/materialien-v1','GitHub-Releases Unterrichtsmaterialien')}. Die Filmdauern wurden aus den bereitgestellten Dateien ermittelt. Die Filme wurden nicht vollständig transkribiert; es werden keine ungeprüften Sequenzzeiten vorgegeben.</p><h2>Bildnachweise</h2><p><strong>Waldersbach / Oberlins Haus:</strong> Patrick Fischer, eigene Aufnahme auf <em>Georg B.</em>, Originaldatei <code>img_4811-3024x4032.jpg</code>. <strong>Strassburg:</strong> Michael Streiff, laut Bildnachweis derselben Seite, Originaldatei <code>strassburg_stadt-1816x2420.jpg</code>. <strong>Büchner:</strong> Porträt nach Alexis Muston, übernommen aus der Woyzeck-Montagewerkstatt / Zurichstories. <strong>Filmposter:</strong> Einzelbilder aus den bereitgestellten Videos, 00:25 bzw. 00:40.</p><h2>Textgestalt und Arbeitsbegriffe</h2><p>Die Lenz-Lesefassung stammt aus dem verlinkten Gutenberg-Text. „L“-Absätze zählen dessen HTML-Absätze; sie sind keine Seiten- oder Zeilenzählung einer kritischen Ausgabe. Der Anfang nennt dort nur „Den 20.“. Celans „20. Jänner“ wird deshalb ausdrücklich als dessen Formulierung behandelt. Gross-/Kleinschreibung und historische Schreibungen bleiben im Lesetext erhalten.</p><p>Einführungen, Aufgaben, Vergleichstabelle und Deutungshilfen sind neue didaktische Texte. Die Intertextualitätswerkstatt unterscheidet explizite Verweise von Vergleichshypothesen. Historische Informationen aus Zurichstories werden von persönlichen Reiseeindrücken unterschieden. </p><p class="source">Quellenprüfung: 23. November 2026. Für wissenschaftliches Zitieren ist die benutzte Textausgabe massgeblich.</p><a href="#auftakt">Zum Lernweg</a></div>`,
unterricht:()=>`<div class="wrap narrow">${head('Für den Unterricht · Sekundarstufe II','Eine Frage führt<br>durch drei Texte.','Vorgeschlagener Umfang: acht bis zehn Lektionen plus Lektürezeit. Die Arbeitswege lassen sich nach Vorwissen und Schwerpunkt verkürzen.')}<ol class="timeline"><li><time>VOR DER REIHE</time><h3>Textgrundlage sichern</h3><p><em>Lenz</em> vollständig lesen. Eine Ausgabe von <em>Gespräch im Gebirg</em> bereitstellen oder die DLA-Lesung gemeinsam hören. Der Meridian steht aus der bereitgestellten Datei im Leseraum. Beim Zitieren die jeweilige Ausgabe kenntlich machen.</p></li><li><time>LEKTIONEN 1–2</time><h3>Im Elsass beginnen</h3><p>Foto, Ankunftsszene und Oberlin-Bericht vergleichen. Lenz, Büchner und Erzähler auseinanderhalten. Aus der Irritation eine Forschungsfrage entwickeln.</p></li><li><time>LEKTIONEN 3–4</time><h3>Mit Celan weitergehen</h3><p><em>Gespräch im Gebirg</em> laut lesen. Anreden und Wiederholungen untersuchen. Nietzsche und Adorno arbeitsteilig erschliessen; Befund und Hypothese unterscheiden.</p></li><li><time>LEKTIONEN 5–6</time><h3>Den Meridian verfolgen</h3><p>Die Kunstfiguren aus Büchners Dramen mit Lenz verbinden. Gegenwort, Atemwende, Daten und Gegenüber in Celans Argumentationsbewegung lesen. Den 20. Januar historisch sorgfältig einordnen.</p></li><li><time>LEKTIONEN 7–8</time><h3>Belege zusammenführen</h3><p>Eine Verbindung pro Gruppe im Textnetz prüfen. Filmsequenzen nach Bedarf einbeziehen. Gegenseitige Rückmeldung zu These, Belegqualität und historischem Vergleich geben.</p></li><li><time>VERTIEFUNG / ABSCHLUSS</time><h3>Ein eigenes Lernprodukt</h3><p>Vergleichs- oder Audioessay ausarbeiten, Gegenbeleg integrieren und revidieren. Das Journal als Text oder Sicherung exportieren. Keine automatische Bewertung und kein gemeinsamer Lernstandserver.</p></li></ol><h2>Beurteilung transparent machen</h2><p>Vier gleichgewichtige Kriterien können die Rückmeldung strukturieren: genaue Textarbeit; Erklärung der intertextuellen Transformation; historische und biografische Differenzierung; nachvollziehbare Argumentation mit Einwand und Revision. Die Checkliste im Journal ist eine Selbsteinschätzung.</p><details><summary>Differenzierung</summary><p>Als Einstieg genügen je eine Textspur pro Werk und vorbereitete Fundstellen. Fortgeschrittene prüfen den Quellenstatus bei Oberlin, die editorische Textgestalt oder Nietzsches Vorrede. Für die Vertiefung können Benjamin / Malebranche und der Schluss der Meridian-Rede hinzukommen. Film und Lesung bieten ergänzende Zugänge; schriftliche Textbelege bleiben für die Abschlussarbeit erforderlich.</p></details><a href="#journal">Zum Journal und Lernprodukt</a></div>`
};
const releaseBase='https://github.com/PatrickFischerKSA/lenz-celan-lernlandschaft/releases/download/materialien-v1/';
const connections=[
{title:'Wer darf sprechen?',kind:'Motiv & historische Verschiebung',from:'Lenz: Selbstbezeichnung vor Oberlin',to:'Gespräch: jüdische Stimmen',text:'Büchners Lenz nennt sich nach Oberlins Rückkehr den ewigen Juden. Celans Gespräch rückt zwei ausdrücklich jüdische Figuren in den Mittelpunkt. Die Verbindung führt von der christlich geprägten Vorstellung ruheloser Wanderschaft zur Frage nach einer eigenen jüdischen Stimme.',focus:'Lies Lenz im Gespräch mit Oberlin und untersuche die Sprechpositionen bei Celan. Wer verwendet eine Bezeichnung für sich selbst, wer für andere? Welche Geschichte wird mit der Bezeichnung aufgerufen?',limit:'Eine christliche, antijüdisch belastete Figur ist nicht mit jüdischer Erfahrung gleichzusetzen. Die Shoah darf im Vergleich nicht zur blossen Metapher allgemeiner Entfremdung werden.',urls:[[S.gutenberg,'Lenz: Oberlins Rückkehr'],[S.gespraech,'Celans Gespräch hören']]},
{title:'Der Gang durchs Gebirg',kind:'Expliziter Rückbezug',from:'Büchner: Lenz',to:'Celan: Gespräch / Meridian',text:'Celan nennt seine kleine Geschichte im Meridian und verbindet sie ausdrücklich mit einem Menschen, den er wie Lenz gehen liess. Diese Selbstkommentierung stützt den Bezug stärker als eine allgemeine Ähnlichkeit von Berglandschaften.',focus:'Vergleiche den Anfang von Lenz, den Anfang des Gesprächs und den Rückblick am Ende des Meridian. Was verändert sich zwischen Bewegung, Sprechen und Selbstbegegnung?',limit:'Die biografischen Wege von Lenz, Büchner und Celan bleiben verschieden. Der Textbezug beweist keine persönliche Wanderung Celans durch das Elsass.',urls:[[S.gutenberg,'Lenz'],[S.gespraech,'Gespräch: DLA-Lesung'],[S.meridian,'Meridian']]},
{title:'Das Medusenhaupt',kind:'Zitat & Umakzentuierung',from:'Lenz: Kunstgespräch',to:'Meridian: Unheimlichkeit der Kunst',text:'Büchners Figur möchte die lebendige Gruppe zweier Mädchen als Bild bewahren. Celan betont dabei die Versteinerung und fragt nach dem Hinaustreten aus dem Menschlichen. Er übernimmt das Bild und verändert dessen Gewicht.',focus:'Lies die Stelle mit den Mädchen und dann Celans Auslegung. Was bedeutet hier der Unterschied zwischen „man möchte“ und „ich möchte“?',limit:'Celans Lektüre ist ausdrücklich akzentuiert. Sie ersetzt nicht alle ästhetischen und sozialen Zusammenhänge des Kunstgesprächs.',urls:[[S.lenz,'Lenz in der MBA'],[S.meridian,'Meridian']]},
{title:'Kreatur & Automat',kind:'Werkübergreifende Montage',from:'Woyzeck / Leonce und Lena',to:'Meridian: Kunst und Mechanismus',text:'Celan stellt Affe, Marionette und Automaten nebeneinander. Die Rede verknüpft Werke Büchners, um nach einer Kunst zu fragen, die das Menschliche im Vorführen und Herstellen zu verlieren droht.',focus:'Untersuche eine Jahrmarktstelle aus Woyzeck. Welche sozialen und sprachlichen Einzelheiten bleiben ausserhalb von Celans Argumentationsweg?',limit:'Der Affe hat im Drama weitere Funktionen. Die Montage ist Celans Verfahren, kein objektives Inhaltsverzeichnis von Büchners Werk.',urls:[[S.woyzeck+'#handschrift','Woyzeck: Original und Umschrift'],[S.meridian,'Meridian']]},
{title:'Auf dem Kopf gehen',kind:'Zitat & poetologisches Bild',from:'Lenz: unmöglicher Schritt',to:'Meridian: Himmel als Abgrund',text:'Ein Moment befremdeter Körper- und Welterfahrung wird bei Celan zum Denkbild. Er fragt, ob Dichtung im Durchgang durch die Fremde einen einzelnen Menschen freisetzen kann.',focus:'Beschreibe den Satz zuerst in seiner erzählerischen Umgebung. Verfolge dann, welche neue Bedeutung Celan aus dem räumlichen Umkehren gewinnt.',limit:'Ein poetologisches Bild ist keine psychiatrische Erklärung der Figur und kein Beweis für eine Gleichheit von Lebenskrisen.',urls:[[S.gutenberg,'Lenz-Anfang'],[S.meridian,'Meridian']]},
{title:'Sonne, Schatten, Gegenüber',kind:'Vergleichshypothese: Nietzsche',from:'Zarathustra: Vorrede',to:'Gespräch im Gebirg',text:'Gebirgsgang, Tageszeit und die Suche nach Hörenden verbinden die Texte als Vergleichskonstellation. Celans abendliche Begegnung zweier jüdischer Figuren lässt sich als Verschiebung der grossen Verkündigung Zarathustras untersuchen.',focus:'Prüfe je eine konkrete Stelle: Wer spricht mit welchem Anspruch? Wer kann zuhören? Wie sind Sonne und Schatten beteiligt?',limit:'Sils Maria liefert einen gemeinsamen Bezugsraum. Ein gemeinsamer Ort allein beweist noch keine Anspielung; die sprachlichen Belege müssen hinzukommen.',urls:[[S.nietzsche,'Nietzsches Vorrede'],[S.sils,'Nietzsche in Sils'],[S.gespraech,'Celan hören']]},
{title:'Eine versäumte Begegnung',kind:'Entstehung & Deutung: Adorno',from:'Engadin 1959',to:'Gespräch / Meridian',text:'Das ausgebliebene Treffen mit Adorno gehört zum Entstehungshorizont. In der Prosa wird das Gespräch sprachlich entworfen; in der Rede erinnert Celan an den Anlass und verbindet ihn mit Selbstbegegnung.',focus:'Welche Frage nach Dichtung nach der Shoah lässt sich am Gespräch zeigen? Wodurch verhindert der Text eine einfache Zuordnung der beiden Figuren zu realen Personen?',limit:'Die Figuren sind keine Transkription von Adorno und Celan. Auch die Behauptung, Adorno habe Gedichte generell verboten, verkürzt seine Kulturkritik.',urls:[[S.adorno,'Seng: Celan und Adorno'],[S.meridian,'Meridian']]},
{title:'Ein Datum bleibt',kind:'Textspur & historischer Resonanzraum',from:'20. Januar 1778 / 1942',to:'Meridian: eingeschriebene Daten',text:'Celan macht den Tag des Lenz-Gangs zur Frage nach der Geschichtlichkeit jedes Gedichts. Der 20. Januar 1942 kann als Resonanzraum mitgelesen werden; er wird in der Rede nicht ausdrücklich genannt.',focus:'Trenne Textbefund, geschichtliches Wissen und deine Deutung. Was gewinnt die Lektüre, wenn sie die Ebenen verbindet? Was würde sie durch eine eindeutige Entschlüsselung verlieren?',limit:'Die Wannsee-Konferenz war nicht der Beginn des Massenmords. Die Rede sagt nicht, jedes Gedicht sei auf dasselbe Datum festzulegen.',urls:[[S.wannsee,'Wannsee: Dokumente'],[S.meridian,'Meridian']]}
];
const lives={
lenz:{intro:'Jakob Michael Reinhold Lenz · 1751–1792',text:'Der historische Dichter gehört zum Sturm und Drang. Büchners Figur gestaltet einen begrenzten Abschnitt seines Lebens; Celans Lektüre blickt über diese Erzählung hinaus.',items:[['1751','Herkunft','Lenz wird in Livland geboren. Sein Weg führt später nach Strassburg; dort entwickelt er eine eigenständige dramatische und ästhetische Position.'],['1770er-Jahre','Sturm und Drang','Mit Dramen wie Der Hofmeister und Die Soldaten richtet sich sein Blick auf soziale Zwänge und beschädigte Lebensmöglichkeiten. Seine Theatertheorie ist ein Hintergrund des Kunstgesprächs.'],['20. Januar bis 8. Februar 1778','Im elsässischen Steintal','Oberlin nimmt Lenz in Waldersbach auf. Seine Beobachtungen werden zu einer zentralen Quelle von Büchners Erzählung.'],['1792','Moskau','Lenz stirbt in Moskau. Celan zitiert im Meridian eine ältere biografische Darstellung seines Todes und fragt zugleich nach der Person in Büchners Text.']],urls:[[S.oberlin,'Dokumente zu Lenz und Oberlin'],[S.meridian,'Celans Rückblick auf Lenz']]},
buechner:{intro:'Georg Büchner · 1813–1837',text:'Ein politisch verfolgter Autor und Naturforscher. Die Materialien aus der Woyzeck-Seite erschliessen Flucht, wissenschaftliche Qualifikation und die letzten Monate in Zürich.',items:[['1813','Goddelau','Büchner wird in Hessen geboren. Sein Studium führt ihn nach Strassburg und Giessen.'],['1834','Der Hessische Landbote','Gemeinsam mit Friedrich Ludwig Weidig arbeitet er an der revolutionären Flugschrift. Sie greift die soziale und politische Ordnung des Grossherzogtums Hessen an. Polizeiliche Verfolgung bedroht die Beteiligten.'],['1835','Flucht nach Strassburg; Arbeit an Lenz','Büchner entzieht sich der drohenden Verhaftung. Die Entstehung von Lenz wird im Wesentlichen mit diesem Jahr verbunden. Literarische Arbeit steht neben politischer Unsicherheit und naturwissenschaftlicher Forschung.'],['1836','Zürich: Anatomie und Lehre','Die Dissertation über das Nervensystem der Barbe führt zum Doktorgrad; die Probevorlesung Über Schädelnerven gehört zum Weg in die Privatdozentur. Zeitgleich arbeitet Büchner literarisch weiter.'],['19. Februar 1837 / 1839','Tod und Nachleben','Büchner stirbt mit 23 Jahren in Zürich. Lenz erscheint 1839 posthum. Überlieferung und Herausgeberentscheidungen prägen den Text, den spätere Leser und Celan vor sich haben.']],urls:[[S.woyzeck+'#entstehung','Woyzeck-Seite: Exil und Zürich'],[S.woyzeck+'#fischpraeparate','Forschung und Präparationspraxis'],[S.edition,'Lenz: Editionsgeschichte'],['https://politischebildung.hessen.de/erinnern/80-jahre-hessen/vorboten-der-demokratie','Politischer Kontext']]},
celan:{intro:'Paul Celan · 1920–1970',text:'Celans Schreiben entsteht aus einer mehrsprachigen Herkunft und der Erfahrung der Shoah. Deutsch bleibt eine Sprache seiner Dichtung, zugleich durch die Geschichte schwer belastet.',items:[['23. November 1920','Czernowitz / damals Rumänien','Paul Antschel wird als Sohn deutschsprachiger jüdischer Eltern geboren. Die Stadt liegt heute als Tscherniwzi in der Ukraine.'],['1942–1944','Verfolgung und Zwangsarbeit','Seine Eltern werden 1942 deportiert; der Vater stirbt im Lager, die Mutter wird erschossen. Celan überlebt rumänische Zwangsarbeitslager. Diese Verfolgung ist Teil der Shoah, kein allgemeines Sinnbild menschlicher Fremdheit.'],['1945–1948','Bukarest, Wien, Paris','Celan arbeitet als Übersetzer und Lektor. Über Wien gelangt er 1948 nach Paris, das sein Lebensmittelpunkt wird.'],['1950er-Jahre','Schreiben, Übersetzen, Beziehungen','Gedichte, Übersetzungen und die Familie mit Gisèle Celan-Lestrange gehören zu seinem Alltag. Die fortgesetzten Plagiatsvorwürfe Claire Golls belasten ihn; Anerkennung und Verletzung stehen nebeneinander.'],['1959','Gespräch im Gebirg','Die Erinnerung an das verpasste Treffen mit Adorno im Engadin wird zu einem Entstehungsanlass. Celan führt die Büchner-Spur weiter und lässt zwei Stimmen im Gebirg sprechen.'],['22. Oktober 1960','Der Meridian','Bei der Büchnerpreisverleihung in Darmstadt macht Celan die Begegnung mit Büchner zum Weg einer eigenen Poetik.'],['1970','Paris','Celan stirbt in Paris. Die Interpretation seiner Texte verlangt die Aufmerksamkeit für ihre sprachliche Arbeit; sie darf nicht allein vom Lebensende her geschlossen werden.']],urls:[[S.celan,'Biografie: Suhrkamp'],['https://www.dla-marbach.de/find/opac/id/BF00013239','DLA: Nachlass und Goll-Affäre'],[S.preis,'Büchnerpreis 1960']]}
};
